<template>
  <div>
    <el-page-header @back="goBack"> </el-page-header>
    <div class="d-flex flex-start" v-loading="loading">
      <el-button
        type="text"
        class="el-icon-circle-plus mr-10"
        @click="addTab(tabIndex)"
      >
      </el-button>
      <el-tabs
        v-model="tabIndex"
        closable
        @tab-remove="removeTab"
        @tab-click="chooseTab"
        size="small"
        style="width: 100%"
        v-if="algorithmList.length > 0"
      >
        <el-tab-pane
          v-for="item in algorithmList"
          :key="item.ai_id"
          :label="item.ai_name"
          :name="item.name"
        >
        </el-tab-pane>
        <el-button
          type="primary"
          size="small"
          v-if="!completedDraw"
          @click="completedDraw = true"
          >绘制区域</el-button
        >
        <el-button
          type="primary"
          size="small"
          v-else
          @click="completedDraw = false"
          >结束绘制</el-button
        >
        <el-button type="primary" size="small" plain @click="reset"
          >清除全部规则</el-button
        >
        <div style="width: 100%; height: 414px" class="mt-10 d-flex">
          <div
            style="
              width: 736px;
              height: 100%;
              background: #000;
              position: relative;
            "
          >
            <videoPlayer
              ref="videoPlayer"
              v-if="videoVisible"
              :src="videoUrl"
              style="height: 100%"
              @resolution-ready="handleResolution"
              @getVideo="getVideo"
              @closeVideo="closeVideo"
            ></videoPlayer>
            <DrawPanel
              style="
                height: 100%;
                z-index: 1;
                position: absolute;
                width: 100%;
                top: 0;
              "
              single
              v-if="canvasVisible"
              ref="canvasVueRef"
              @finish="handleDrawFinish"
              :completedDraw="completedDraw"
              :pointArr="formData.area"
              :ratio="ratio"
              :fullScreen="fullScreen"
            />
          </div>

          <div class="ml-20">
            <span class="f-bold fs-16">属性配置</span>
            <el-form
              :model="formData"
              ref="formData"
              label-width="200px"
              size="small"
              style="width: 80%"
            >
              <el-form-item label="报警时间间隔(秒):">
                <el-input-number
                  v-model="formData.interval"
                  :min="0"
                  :step="0.1"
                >
                </el-input-number>
              </el-form-item>
              <el-form-item label="报警阈值:">
                <el-input-number
                  v-model="formData.threshold"
                  :min="0"
                  :step="0.1"
                  :max="1"
                >
                </el-input-number>
              </el-form-item>
              <el-button type="primary" style="float: right" @click="saveData"
                >保存</el-button
              >
            </el-form>
          </div>
        </div>
      </el-tabs>
      <el-empty v-else description="暂无内容" style="width: 100%"></el-empty>
      <el-drawer :visible.sync="sceneVisble" size="40%">
        <div class="p-20" style="position: relative">
          <el-tabs v-model="activeName" @tab-click="handleClick">
            <el-tab-pane label="场景" name="1">
              <el-collapse @change="handleChange" accordion>
                <el-collapse-item
                  :title="item.scene_name"
                  :name="index"
                  v-for="(item, index) in sceneList"
                  :key="index"
                >
                  <el-checkbox-group size="small" v-model="checkedTabs">
                    <el-checkbox
                      @change="handleCheckedTabs"
                      v-for="value in item.children"
                      :label="JSON.stringify(value)"
                      :key="value.ai_id"
                      border
                      >{{ value.ai_name }}</el-checkbox
                    >
                  </el-checkbox-group>
                </el-collapse-item>
              </el-collapse>
            </el-tab-pane>
            <el-tab-pane label="算法" name="2">
              <el-checkbox-group size="small" v-model="checkedTabs">
                <el-checkbox
                  @change="handleCheckedTabs"
                  v-for="value in dataAiList"
                  :label="JSON.stringify(value)"
                  :key="value.ai_id"
                  border
                  >{{ value.ai_name }}</el-checkbox
                >
              </el-checkbox-group>
            </el-tab-pane>
          </el-tabs>
        </div>
        <div style="position: absolute; bottom: 10px; right: 10px">
          <el-button @click="sceneVisble = false" size="small">取 消</el-button>
        </div>
      </el-drawer>
    </div>
  </div>
</template>

<script>
import DrawPanel from "@/components/drawPanel.vue";
import videoPlayer from "@/components/videoPlayer.vue";
import { getUrl } from "@/assets/utils/config";

export default {
  components: {
    DrawPanel,
    videoPlayer,
  },
  data() {
    return {
      tabIndex: "0",
      algorithmList: [],
      formData: {
        area: [],
        threshold: 0.5,
        interval: 60,
      },
      videoUrl: "",
      canvasVisible: false,
      sceneVisble: false,
      sceneList: [],
      activeNames: 0,
      checkAll: false,
      checkedTabs: [],
      isIndeterminate: true,
      ratio: 1,
      completedDraw: false,
      pointArr: [],
      fullScreen: false,
      pro_id: "",
      loading: false,
      videoVisible: false,
      videLoad: false,
      activeName: "1",
      dataAiList: [],
      source_id: "",
    };
  },
  created() {
    this.pro_id = Number(this.$route.query.pro_id);
    this.getSceneList();
    this.getAlgorithmList();
    this.getDataAiPropertyList();
  },
  beforeRouteLeave(to, from, next) {
    if (to.name == "collectionConfiguration") {
      const { source_id, sourceTab, page } = this.$route.query;
      to.query.source_id = source_id;
      to.query.sourceTab = sourceTab;
      to.query.page = page;
    }
    next();
  },
  mounted() {},
  methods: {
    getAlgorithmList() {
      this.$api.get(`/ai/getDataAiList`).then((res) => {
        if (res.data.data) {
          this.dataAiList = res.data.data.map((item) => {
            return {
              ai_id: item.id,
              ai_name: item.ai_name,
            };
          });
        }
      });
    },
    handleClick() {},
    closeVideo() {
      this.$api.get("/media/stopPlay", {
        params: { id: this.pro_id },
      });
    },
    goBack() {
      this.$router.back();
    },
    // 获取比例
    handleResolution(e) {
      this.ratio = e.boxWdith / e.videoWidth;
      this.videLoad = true;
      this.canvasVisible = true;
    },
    getVideo() {
      this.$api
        .get("/media/play", { params: { id: this.pro_id } })
        .then((res) => {
          if (res.data.data.play_url) {
            this.videoUrl = getUrl(res.data.data.play_url);
            // this.videoUrl = res.data.data.play_url.replace(
            //   "127.0.0.1",
            //   "192.168.0.107"
            // );
            this.videoVisible = true;
          } else {
            this.$message.warning("操作成功");
          }
        });
    },
    chooseTab() {
      this.completedDraw = false;
      this.getDataAiPropertyList();
    },
    // 保存数据
    saveData() {
      this.formData.ai_id = this.algorithmList[this.tabIndex].ai_id;
      this.formData.ai_pro_id = this.algorithmList[this.tabIndex].ai_pro_id;
      this.formData.area = JSON.stringify(this.formData.area);
      this.$api.post("/ai/updateDataAiProperty", this.formData).then(() => {
        this.getDataAiPropertyList();
        this.$message.success("操作成功");
      });
    },
    // ai与属性关系列表
    async getDataAiPropertyList() {
      this.loading = true;
      this.canvasVisible = false;
      this.checkedTabs = [];
      this.$api
        .get("/ai/getDataAiPropertyList", {
          params: { pro_id: this.pro_id },
        })
        .then((r) => {
          if (r.data.data) {
            this.algorithmList =
              r.data.data.map((item, index) => {
                return {
                  ...item,
                  name: index.toString(),
                };
              }) || [];
            this.checkedTabs = r.data.data.map((item) => {
              let data = {
                ai_id: item.ai_id,
                ai_name: item.ai_name,
              };
              return JSON.stringify(data);
            });
            let data = this.algorithmList[this.tabIndex];
            this.formData = {
              ...data,
              area: data.area ? JSON.parse(data.area) : [],
              threshold: data.threshold || 0.5,
              interval: data.interval || 60,
            };
            if (this.videoUrl) {
              this.canvasVisible = this.videLoad;
            } else {
              this.getVideo();
            }
          } else {
            this.algorithmList = [];
          }
        })
        .finally(() => {
          this.loading = false;
        });
    },
    // 清空画布
    reset() {
      this.$refs.canvasVueRef.reset();
      this.formData.area = [];
    },
    // 绘制完成
    handleDrawFinish(e) {
      // 编辑的时候不需要二次计算
      let region = e.map((item) => {
        return {
          x: item.x / this.ratio,
          y: item.y / this.ratio,
        };
      });
      this.formData.area.push(region);
    },
    // 获取场景列表
    getSceneList() {
      this.$api.get("/ai/getDataSceneList").then((res) => {
        this.sceneList = res.data.data;
      });
    },
    // 展开场景
    async handleChange(e) {
      if (e !== "") {
        let res = await this.$api.get("/ai/getDataAiSceneList", {
          params: {
            scene_id: this.sceneList[e].scene_id,
          },
        });
        if (res.data.data) {
          let data = res.data.data.map((item) => {
            return {
              ai_id: item.ai_id,
              ai_name: item.ai_name,
            };
          });
          this.$set(this.sceneList[e], "children", data);
        }
      }
    },
    // 选择分类
    handleCheckedTabs(checked, e) {
      let data = JSON.parse(e.target.value);
      let url = checked ? "/ai/addDataAiProperty" : "/ai/delDataAiProperty";
      this.$api
        .post(url, {
          pro_id: this.pro_id,
          ai_id: [data.ai_id],
        })
        .then(() => {
          this.getDataAiPropertyList();
          this.$message.success("操作成功");
          this.tabIndex = "0";
        });
    },

    addTab() {
      this.sceneVisble = true;
    },
    // 删除标签
    removeTab(targetName) {
      this.$api
        .post("/ai/delDataAiProperty", {
          pro_id: this.pro_id,
          ai_id: [this.algorithmList[targetName].ai_id],
        })
        .then(() => {
          this.getDataAiPropertyList();
          this.tabIndex = "0";
          this.$message.success("操作成功");
        });
    },
  },
  beforeDestroy() {
    this.videoVisible = false;
  },
};
</script>

<style lang="scss" scoped>
::v-deep .el-checkbox.is-bordered.el-checkbox--small {
  margin: 0 5px 5px 0 !important;
}
::v-deep .el-drawer__header {
  margin-bottom: 0 !important;
  padding-top: 10px !important ;
}
</style>
